public class CastViewHelper54 {
    private static String report(Boolean accepted, Boolean resultNull, String castType, String castMessage) {
        String reflectionType, reflectionMessage;
        String element = castMessage?.substringBetween('List<', '>');
        Type reflected;
        try { reflected = Type.forName(element); }
        catch (Exception error) { reflectionType = error.getTypeName(); reflectionMessage = error.getMessage(); }
        return JSON.serialize(new Map<String,Object>{
            'accepted'=>accepted, 'resultNull'=>resultNull, 'castType'=>castType, 'castMessage'=>castMessage,
            'element'=>element, 'reflectedName'=>reflected?.getName(),
            'reflectionType'=>reflectionType, 'reflectionMessage'=>reflectionMessage});
    }
    private static String inspect(Object boxed) {
        Boolean accepted = false; Boolean resultNull; String castType, castMessage;
        try { Account discarded = (Account)boxed; resultNull = discarded == null; accepted = true; }
        catch (Exception error) { castType = error.getTypeName(); castMessage = error.getMessage(); }
        return report(accepted, resultNull, castType, castMessage);
    }
    private static String inspectTarget(Object boxed) {
        Boolean accepted = false; Boolean resultNull; String castType, castMessage;
        try { CastProbeTarget__c discarded = (CastProbeTarget__c)boxed; resultNull = discarded == null; accepted = true; }
        catch (Exception error) { castType = error.getTypeName(); castMessage = error.getMessage(); }
        return report(accepted, resultNull, castType, castMessage);
    }
    public static String listView(List<Object> value) { return inspect(value); }
    public static String objectView(Object value) { return inspect(value); }
    public static String recordView(List<SObject> value) { return inspect(value); }
    public static String targetView(List<Object> value) { return inspectTarget(value); }
}

